{
  "technical_and_design_decisions": [
    "U1: Namespace isolation for ZK metadata will be implemented via a configurable property (e.g., zk.namespace) in the application configuration, applied at ZK client creation.",
    "U2: Interactive authentication will be added using Spring Security's authentication mechanism, with the shell prompting for credentials and sending them securely over HTTPS.",
    "U3: A maintenance branch (e.g., 'maint/v1.0.x') will be created from the release tag; CI/CD pipelines will be configured to build and deploy from this branch for minor releases.",
    "U4: Deprecated functions (e.g., module definition download) will be identified via @Deprecated annotations and usage search; removal will be done with accompanying test updates.",
    "U5: After spike research, the chosen approach is to have xd-shell discover the admin server port via Zookeeper ephemeral nodes (direct ZK connection) for simplicity, with a fallback to a load balancer if needed.",
    "U6: Kafka consumer will be upgraded to the 0.9+ consumer API (org.apache.kafka.clients.consumer.KafkaConsumer), requiring changes to consumer configuration and polling logic.",
    "U7: Spike will focus on feasibility of Motion-JPEG streaming ingestion using JavaCV/FFmpeg; design specs will outline data format, pipeline stages, and integration points.",
    "U8: Configuration parameter 'cluster.view.messageRates.enabled' will be added to servers.yml, bound to a Spring @ConfigurationProperties bean, and used to conditionally render message rates in the Admin UI cluster view."
  ],
  "assumptions": [
    "The codebase is a Spring Boot / Spring XD project using Zookeeper for service discovery, Kafka for messaging, and an embedded Tomcat for the admin server.",
    "The developer has full access to the source code, build system (Maven/Gradle), and CI/CD configuration.",
    "Existing test suites (unit, integration) cover the affected areas and can be extended.",
    "Spikes (U5a, U7a, U7b) are time-boxed research activities; no production code is delivered from them except documentation.",
    "U3 is primarily a DevOps/process task; effort includes branch creation, CI pipeline updates, and documentation.",
    "All estimates assume a single developer working full-time (8 hours/day) with no interruptions.",
    "Third-party library upgrades (Kafka, OpenCV) are compatible with Java 17+ (Spring Framework 6.0 baseline)."
  ],
  "activities": [
    {
      "activity_id": "A1",
      "activity_name": "Implement ZK namespace configuration for multi-tenancy",
      "activity_description": "Design and implement a configurable namespace property for Zookeeper metadata isolation per tenant. Includes configuration schema changes, ZK client initialization updates, and integration tests.",
      "most_likely_effort": 5
    },
    {
      "activity_id": "A2",
      "activity_name": "Implement interactive username/password authentication for Admin server",
      "activity_description": "Add interactive credential prompt in xd-shell and configure Admin server to accept username/password via Spring Security. Ensure credentials are not logged. Includes security configuration, shell changes, and tests.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A3",
      "activity_name": "Set up maintenance branch and CI/CD for minor releases",
      "activity_description": "Create a maintenance branch from the latest release tag, configure CI pipelines (e.g., GitHub Actions/Jenkins) to build and deploy from this branch, and document the release process for minor versions.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A4",
      "activity_name": "Clean up deprecated functions across codebase, Shell, and Admin-UI modules",
      "activity_description": "Identify and remove deprecated code (e.g., module definition download), update references, and ensure all tests pass. Includes changes in core, shell, and admin-ui modules.",
      "most_likely_effort": 6
    },
    {
      "activity_id": "A5a",
      "activity_name": "Spike research for xd-shell connection to admin server (direct ZK vs LB)",
      "activity_description": "Research and evaluate approaches for xd-shell to discover the admin server's random port: direct Zookeeper connection vs load balancer. Document findings and recommendation.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A5b",
      "activity_name": "Implement chosen solution for xd-shell to access admin server random port",
      "activity_description": "Implement the selected discovery mechanism (Zookeeper ephemeral nodes) in xd-shell, integrate with existing shell commands, and add integration tests for HA scenarios.",
      "most_likely_effort": 5
    },
    {
      "activity_id": "A6a",
      "activity_name": "Upgrade Kafka consumer to 0.9+ rewrite API",
      "activity_description": "Update Kafka client dependency to 0.9+, migrate consumer code to the new KafkaConsumer API, adjust configuration properties, and verify compilation.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A6b",
      "activity_name": "Fix failing tests after Kafka consumer upgrade",
      "activity_description": "Run the test suite, diagnose and fix failures related to the new consumer API (e.g., polling behavior, offset management, serialization). Update test mocks and integration tests as needed.",
      "most_likely_effort": 5
    },
    {
      "activity_id": "A7a",
      "activity_name": "Spike research feasibility of Motion-JPEG for audio/video streaming ingestion",
      "activity_description": "Investigate Motion-JPEG suitability for streaming ingestion, evaluate Java libraries (JavaCV, FFmpeg), and prototype a minimal ingestion pipeline. Document feasibility and risks.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A7b",
      "activity_name": "Create design specs for Motion-JPEG format and ingestion pipeline",
      "activity_description": "Produce design documentation covering Motion-JPEG data format, streaming pipeline architecture, integration with predictive analytics, and platform compatibility considerations.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A8",
      "activity_name": "Add config parameter to enable/disable message rates in cluster view",
      "activity_description": "Add 'cluster.view.messageRates.enabled' property in servers.yml, bind to configuration bean, modify backend to conditionally collect message rates, and update Admin UI cluster view to respect the setting.",
      "most_likely_effort": 2
    }
  ],
  "reported_total": {
    "most_likely_effort": 43
  }
}

